def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()

    # Legend: full-height single-colour columns not of the shape colour (8).
    shape_col = 8
    legend = []
    for x in range(W):
        col = g[:, x]
        if col[0] != bg and col[0] != shape_col and np.all(col == col[0]):
            legend.append((x, int(col[0])))
    for x, _ in legend:
        out[:, x] = bg
    emit(out, "Erase the legend lines; their colours (left to right) will paint the cyan blocks.")

    # Split grey area into blocks: maximal runs of adjacent columns with identical grey-row sets.
    blocks = []
    prev = None
    for x in range(W):
        rows = tuple(np.where(g[:, x] == shape_col)[0])
        if not rows:
            prev = None
            continue
        if prev is not None and rows == prev and blocks and blocks[-1][1] == x - 1:
            blocks[-1][1] = x
        else:
            blocks.append([x, x, rows])
        prev = rows

    colours = [c for _, c in legend]
    for i, (x0, x1, rows) in enumerate(blocks):
        if i >= len(colours):
            break
        c = colours[i]
        for x in range(x0, x1 + 1):
            for y in rows:
                out[y, x] = c
        emit(out, f"Block {i+1} (columns {x0}-{x1}) takes legend colour {c}.")

    emit(out, "All cyan blocks recoloured in legend order.")
    return out
